 import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, texture, mix, smoothstep, mul, add, sin, fract } from 'three/tsl';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const { Mesh, Group, PlaneGeometry, Color } = THREE;

  const colors = config.intent?.visualSpec?.colors ?? config.colors ?? {};
  const ink = new Color(colors.ink ?? '#16161d');
  const paper = new Color(colors.paper ?? '#e8ecf2');
  const surface = new Color(colors.surface ?? '#0b0b10');

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const headlineItem = items.find((i) => i.role === 'headline') ?? items[0] ?? {};
  const headline = headlineItem.text ?? 'Collection';

  const root = new Group();
  root.name = config.id ?? 'collection-title';

  const planeW = 3.2;
  const planeH = 2.0;
  const geometry = new PlaneGeometry(planeW, planeH);
  const material = new MeshBasicNodeMaterial({ transparent: true });

  const fallbackNode = vec3(mix(surface, ink, smoothstep(0.0, 1.0, uv().y)));
  material.colorNode = fallbackNode;

  const card = new Mesh(geometry, material);
  card.name = 'title-card';
  root.add(card);

  let loadedTexture = null;

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl)
      .then((tex) => {
        loadedTexture = tex;
        tex.colorSpace = THREE.SRGBColorSpace ?? 'srgb';
        tex.anisotropy = 4;

        const texNode = texture(tex, uv());
        const noiseUV = add(mul(uv().x, 12.9898), mul(uv().y, 78.233));
        const n = fract(mul(sin(noiseUV), 43758.5453));
        const grain = mix(0.97, 1.03, n);

        material.colorNode = texNode.rgb.mul(grain);
        material.opacityNode = texNode.a;
        material.needsUpdate = true;
      })
      .catch(() => {
        // keep the engineered gradient fallback
      });
  }

  const label = ctx.fontAtlas.createText(headline, {
    fontSize: headlineItem.typography?.fontSize ?? 96,
    color: paper,
    align: 'center'
  });
  label.position.set(0, 0.65, 0.05);
  root.add(label);

  root.userData.handlers = {};
  root.userData.timelines = [];

  root.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (loadedTexture) loadedTexture.dispose();

    root.traverse((child) => {
      if (child === root) return;
      if (child.geometry) child.geometry.dispose();
      if (child.material) {
        if (Array.isArray(child.material)) {
          child.material.forEach((m) => m.dispose());
        } else {
          child.material.dispose();
        }
      }
    });
  };

  return root;
}
